cssCode:
.magnetic-fab {
  position: absolute; width: 60px; height: 60px;
  background: radial-gradient(circle, #ff007f, #b30059);
  border-radius: 50%; box-shadow: 0 10px 20px rgba(255,0,127,0.5);
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 24px; cursor: grab; touch-action: none;
  transition: top 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), left 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.magnetic-fab.dragging { transition: none; cursor: grabbing; }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;';

const fab = document.createElement('div');
fab.className = 'magnetic-fab';
fab.innerText = '💬';
fab.style.top = '50%'; fab.style.left = '10px';
c.appendChild(fab);

let isDraggingFab = false, offsetX, offsetY;

fab.addEventListener('pointerdown', (e) => {
  isDraggingFab = true;
  fab.classList.add('dragging');
  const rect = fab.getBoundingClientRect();
  offsetX = e.clientX - rect.left;
  offsetY = e.clientY - rect.top;
});

document.addEventListener('pointermove', (e) => {
  if (!isDraggingFab) return;
  const cRect = c.getBoundingClientRect();
  let x = e.clientX - cRect.left - offsetX;
  let y = e.clientY - cRect.top - offsetY;
  fab.style.left = `${x}px`; fab.style.top = `${y}px`;
});

document.addEventListener('pointerup', () => {
  if (!isDraggingFab) return;
  isDraggingFab = false;
  fab.classList.remove('dragging');
  const cRect = c.getBoundingClientRect();
  const fabRect = fab.getBoundingClientRect();

  // Snap to nearest edge (Left or Right)
  const centerX = fabRect.left + fabRect.width / 2 - cRect.left;
  if (centerX < cRect.width / 2) {
    fab.style.left = '10px';
  } else {
    fab.style.left = `${cRect.width - 70}px`;
  }

  // Keep within top/bottom bounds
  let currentY = parseFloat(fab.style.top);
  if (currentY < 10) fab.style.top = '10px';
  if (currentY > cRect.height - 70) fab.style.top = `${cRect.height - 70}px`;
});
